package io.github.diodeme.ji.stage6;

import io.github.diodeme.ji.agent.core.ToolBatchScheduler;
import io.github.diodeme.ji.ai.*;
import io.github.diodeme.ji.artifact.*;
import io.github.diodeme.ji.artifact.fs.FileArtifactStore;
import io.github.diodeme.ji.extension.*;
import io.github.diodeme.ji.host.*;
import io.github.diodeme.ji.host.sqlite.SqliteHostStorePersistence;
import io.github.diodeme.ji.session.tree.SessionDocument;
import java.nio.ByteBuffer;
import java.nio.file.*;
import java.security.MessageDigest;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;

/** Fixed-scale production-like Stage 6 gate for the 2 vCPU / 4 GiB baseline. */
final class Stage6Performance {
    private static final int SESSIONS = 1_000;
    private static final int ITEMS_PER_SESSION = 100;
    private static final int REPLAY_EVENTS = 10_000;
    private static final long ARTIFACT_BYTES = 2L * ArtifactLimits.GIB;
    private static final Instant NOW = Instant.parse("2026-09-06T00:00:00Z");

    private Stage6Performance() {}

    static void run(Path directory) throws Exception {
        Files.createDirectories(directory);
        Path database = directory.resolve("host.db");
        try (HostStore store = new PersistentHostStore(new SqliteHostStorePersistence(database))) {
            populate(store);
        }
        long coldStart = System.nanoTime();
        long[] postGc;
        try (HostStore store = new PersistentHostStore(new SqliteHostStorePersistence(database))) {
            metric("coldReadyMillis", millis(coldStart), 8_000);
            measureQueries(store);
            measureAckAndReplay(store);
            measureTools();
            postGc = measurePostGc(store);
        }
        measureArtifact(directory.resolve("artifacts"));
        long rss = processRss();
        metric("rssBytes", rss, 2L * ArtifactLimits.GIB);
        System.out.printf(Locale.ROOT,
                "{\"status\":\"passed\",\"sessions\":%d,\"transcriptItems\":%d,\"replayEvents\":%d,\"artifactBytes\":%d,\"clients\":2,\"activeRuns\":2,\"toolEffects\":16,\"postGcBaselineBytes\":%d,\"postGcFinalBytes\":%d}%n",
                SESSIONS, SESSIONS * ITEMS_PER_SESSION, REPLAY_EVENTS, ARTIFACT_BYTES,
                postGc[0], postGc[postGc.length - 1]);
        System.out.println("STAGE6_PERFORMANCE_OK");
    }

    private static void populate(HostStore store) {
        for (int session = 0; session < SESSIONS; session++) {
            String id = "session-" + session;
            SessionDocument document = store.create(id, new ModelRef("faux", "model"), "workspace", NOW);
            for (int item = 0; item < ITEMS_PER_SESSION; item++) {
                int value = item;
                document = store.update(id, document.revision(), current -> current.appendEntry(
                        "main", id + "-message-" + value, SessionDocument.EntryKind.MESSAGE,
                        Optional.of(new Message(id + "-message-" + value,
                                value % 2 == 0 ? Message.Role.USER : Message.Role.ASSISTANT,
                                List.of(new Content.Text("indexed transcript item " + value)), NOW.plusSeconds(value))),
                        Map.of(), NOW.plusSeconds(value)));
            }
        }
        // Two clients and two active runs are explicit durable facts on separate Sessions.
        for (int index = 0; index < 2; index++) {
            int value = index;
            String id = "session-" + value;
            SessionDocument current = store.load(id).orElseThrow();
            String run = "active-run-" + value;
            store.acceptPrompt(id, "client-command-" + value, "payload-" + value, run,
                    current.revision(), "client-" + value, List.of("active"), List.of());
            store.update(id, current.revision(), document -> document.startRun(new SessionDocument.RunStart(
                    run, "turn-" + value, "attempt-" + value, "result-" + value,
                    new Message("prompt-" + value, Message.Role.USER, List.of(new Content.Text("active")), NOW),
                    "operation-" + value, "attempt-record-" + value, NOW)));
        }
    }

    private static void measureQueries(HostStore store) {
        long list = p95Millis(20, () -> store.listSummaries(
                io.github.diodeme.ji.session.tree.SessionRepository.SummaryQuery.firstPage(Optional.empty())));
        metric("listP95Millis", list, 500);
        long search = p95Millis(20, () -> store.search(HostStore.SearchQuery.firstPage("indexed")));
        metric("searchP95Millis", search, 500);
        long first = p95Millis(20, () -> store.timeline("session-999",
                new HostStore.TimelineQuery(OptionalLong.empty(), 50)));
        metric("sessionFirstPageP95Millis", first, 750);
    }

    private static void measureAckAndReplay(HostStore store) {
        String id = "session-2";
        SessionDocument current = store.load(id).orElseThrow();
        store.acceptPrompt(id, "replay-anchor", "anchor-hash", "anchor-result",
                current.revision(), "client-0", List.of("active"), List.of());
        int existingEvents = store.replay(id, 0).size();
        int requiredEvents = REPLAY_EVENTS - existingEvents;
        int acknowledgementSamples = 50;
        if (requiredEvents < acknowledgementSamples * 2) fail("replayEvents", existingEvents);
        long[] acknowledgementMillis = new long[acknowledgementSamples];
        for (int index = 0; index < acknowledgementMillis.length; index++) {
            String commandId = "replay-command-" + index;
            String payloadHash = "hash-" + index;
            String resultRef = "replay-result-" + index;
            long start = System.nanoTime();
            HostStore.PromptAcceptance accepted = store.acceptPrompt(
                    id, commandId, payloadHash, resultRef, current.revision(),
                    "client-" + (index & 1), List.of("queued"), List.of());
            acknowledgementMillis[index] = millis(start);
            store.remove(id, commandId, "client-" + (index & 1), accepted.queueRevision());
        }
        HostStorePersistence.ComposerConfig config = store.composerConfig(id);
        for (int index = acknowledgementSamples * 2; index < requiredEvents; index++) {
            String reasoning = (index & 1) == 0 ? "stage6-a" : "stage6-b";
            config = store.updateComposerConfig(id, config.revision(), config.profileRevision(),
                    config.profileId(), config.modelId(), reasoning, config.permissionMode());
        }
        Arrays.sort(acknowledgementMillis);
        metric("ackP95Millis", acknowledgementMillis[(int) Math.ceil(acknowledgementMillis.length * 0.95) - 1], 150);
        long replay = System.nanoTime();
        List<HostStore.DurableEvent> events = store.replay(id, 0);
        metric("replayRecoveryMillis", millis(replay), 2_000);
        if (events.size() != REPLAY_EVENTS) fail("replayEvents", events.size());
    }

    private static void measureTools() throws Exception {
        var workspace = new WorkspaceProvider.WorkspaceIdentity("workspace", 0);
        AtomicInteger active = new AtomicInteger();
        AtomicInteger maximum = new AtomicInteger();
        CountDownLatch entered = new CountDownLatch(16);
        CountDownLatch release = new CountDownLatch(1);
        try (var executor = Executors.newVirtualThreadPerTaskExecutor();
             var scheduler = new ToolBatchScheduler(context -> ToolExecutionPolicy.Evaluation.allow(
                     false, PermissionDecider.RiskLevel.LOW, "stage6"),
                     (request, cancellation) -> CompletableFuture.completedFuture(
                             PermissionDecider.Decision.allow(request, NOW)), List.of(), executor,
                     Clock.fixed(NOW, ZoneOffset.UTC), 8, 16, 32)) {
            var requests = new ArrayList<ToolBatchScheduler.ToolRequest<Integer>>();
            for (int index = 0; index < 16; index++) {
                int value = index;
                String session = index < 8 ? "tool-session-a" : "tool-session-b";
                var context = new ToolExecutionPolicy.Context("host", session, "actor", "test", workspace,
                        "tool-" + index, "test", Map.of(), 0, NOW);
                requests.add(new ToolBatchScheduler.ToolRequest<>(context, "operation-" + index, 0,
                        null, ToolRetryContract.NON_RETRYABLE, null, ToolBatchScheduler.Lifecycle.unmanaged(),
                        ignored -> true, () -> {
                            int count = active.incrementAndGet();
                            maximum.accumulateAndGet(count, Math::max);
                            entered.countDown();
                            try { release.await(); } catch (InterruptedException failure) {
                                Thread.currentThread().interrupt(); throw new IllegalStateException(failure);
                            } finally { active.decrementAndGet(); }
                            return value;
                        }));
            }
            var completion = scheduler.execute(requests, CancellationToken.NONE).toCompletableFuture();
            if (!entered.await(10, TimeUnit.SECONDS) || maximum.get() != 16) fail("toolEffects", maximum.get());
            release.countDown();
            completion.get(10, TimeUnit.SECONDS);
        }
    }

    private static void measureArtifact(Path root) throws Exception {
        byte[] chunk = new byte[Math.toIntExact(ArtifactLimits.defaults().chunkBytes())];
        for (int index = 0; index < chunk.length; index++) chunk[index] = (byte) (index * 31);
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        for (long offset = 0; offset < ARTIFACT_BYTES; offset += chunk.length) digest.update(chunk);
        String sha256 = HexFormat.of().formatHex(digest.digest());
        try (var store = new FileArtifactStore(root, ArtifactLimits.defaults())) {
            var upload = store.beginUpload(new ResumableUpload(
                    new ArtifactScope("host", "workspace", "artifact-session"), "application/octet-stream",
                    "2gib.bin", ARTIFACT_BYTES, sha256), NOW);
            for (int index = 0; index < upload.chunkCount(); index++) {
                store.putChunk(upload.uploadId(), new UploadChunk(index, chunk), NOW);
            }
            ArtifactReceipt receipt = store.complete(upload.uploadId(), NOW);
            if (receipt.size() != ARTIFACT_BYTES || store.usage().storedBytes() != ARTIFACT_BYTES) {
                fail("artifactBytes", receipt.size());
            }
            byte[] first = store.read(receipt.artifactId(), new ArtifactScope("host", "workspace", "artifact-session"),
                    new ByteRange(0, 1023)).bytes();
            if (first.length != 1024) fail("artifactRange", first.length);
        }
    }

    private static long[] measurePostGc(HostStore store) throws Exception {
        long[] values = new long[4];
        for (int sample = 0; sample < values.length; sample++) {
            measureQueries(store);
            byte[] pressure = new byte[32 * 1024 * 1024];
            pressure[pressure.length - 1] = (byte) sample;
            pressure = null;
            for (int collection = 0; collection < 3; collection++) {
                System.gc();
                Thread.sleep(250);
            }
            values[sample] = usedHeap();
            metric("postGcSample" + sample + "Bytes", values[sample], 2L * ArtifactLimits.GIB);
        }
        long baseline = values[0];
        long finalValue = values[values.length - 1];
        long allowedGrowth = Math.max(1L, baseline / 20);
        if (finalValue > baseline + allowedGrowth) fail("postGcGrowth", finalValue - baseline);
        System.out.printf(Locale.ROOT,
                "{\"metric\":\"postGcGrowthBytes\",\"value\":%d,\"baseline\":%d,\"limitPercent\":5}%n",
                finalValue - baseline, baseline);
        return values;
    }

    private static long p95Millis(int samples, Runnable operation) {
        long[] values = new long[samples];
        for (int index = 0; index < samples; index++) {
            long start = System.nanoTime(); operation.run(); values[index] = millis(start);
        }
        Arrays.sort(values);
        return values[(int) Math.ceil(samples * 0.95) - 1];
    }
    private static long millis(long started) { return TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - started); }
    private static long usedHeap() { Runtime runtime = Runtime.getRuntime(); return runtime.totalMemory() - runtime.freeMemory(); }
    private static long processRss() throws Exception {
        Path status = Path.of("/proc/self/status");
        if (!Files.isRegularFile(status)) return usedHeap();
        return Files.readAllLines(status).stream().filter(line -> line.startsWith("VmRSS:"))
                .map(line -> line.replaceAll("[^0-9]", "")).filter(value -> !value.isBlank())
                .mapToLong(Long::parseLong).findFirst().orElseThrow() * 1024;
    }
    private static void metric(String name, long value, long limit) {
        System.out.printf(Locale.ROOT, "{\"metric\":\"%s\",\"value\":%d,\"limit\":%d}%n", name, value, limit);
        if (value > limit) fail(name, value);
    }
    private static void fail(String metric, long value) { throw new IllegalStateException(metric + " gate failed: " + value); }
}

